<?php
require_once __DIR__.'/config/db.php';require_once __DIR__.'/includes/functions.php';garantir_schema_expandido($pdo);exigir_login();processar_acao_favorito($pdo);
$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM times WHERE id=?');$q->execute([$id]);$time=$q->fetch();
$titulo_pagina='SUBZERO · Perfil do time';require __DIR__.'/includes/header.php';
if(!$time){http_response_code(404);?><section class="container section"><div class="alert alert-error">Time não encontrado.</div><a class="btn btn--ghost" href="classificacao.php">Voltar à classificação</a></section><?php require __DIR__.'/includes/footer.php';exit;}
$tab=calcular_classificacao($pdo);$pos=1;$linha=null;foreach($tab as $i=>$r)if((int)$r['id']===$id){$pos=$i+1;$linha=$r;break;}
$q=$pdo->prepare('SELECT c.*,CASE WHEN c.time_casa=? THEN tv.nome ELSE tc.nome END AS adversario,CASE WHEN c.time_casa=? THEN c.gols_casa ELSE c.gols_visitante END AS gf,CASE WHEN c.time_casa=? THEN c.gols_visitante ELSE c.gols_casa END AS ga FROM confrontos c JOIN times tc ON tc.id=c.time_casa JOIN times tv ON tv.id=c.time_visitante WHERE c.time_casa=? OR c.time_visitante=? ORDER BY (c.data_hora IS NULL),c.data_hora,c.id');$q->execute([$id,$id,$id,$id,$id]);$jogos=$q->fetchAll();
$q=$pdo->prepare("SELECT j.id,j.nome,j.numero,j.jogos_ajuste,j.pontos_ajuste,COALESCE(SUM(CASE WHEN c.confirmado=1 THEN s.gols ELSE 0 END),0) AS gols,COALESCE(SUM(CASE WHEN c.confirmado=1 THEN s.assistencias ELSE 0 END),0) AS assistencias,(SELECT COUNT(*) FROM confrontos cj WHERE cj.confirmado=1 AND (cj.time_casa=j.time_id OR cj.time_visitante=j.time_id)) AS jogos_confirmados FROM jogadores j LEFT JOIN sumulas s ON s.jogador_id=j.id LEFT JOIN confrontos c ON c.id=s.confronto_id AND c.confirmado=1 WHERE j.time_id=? GROUP BY j.id,j.nome,j.numero,j.time_id,j.jogos_ajuste,j.pontos_ajuste ORDER BY j.numero");$q->execute([$id]);$elenco=$q->fetchAll();
?><section class="page-hero page-hero-sm"><div class="page-hero-overlay"></div><div class="container page-hero-content"><p class="eyebrow">Perfil da equipe</p><h1 class="page-title"><?=e($time['nome'])?></h1><?=botao_favorito($pdo, 'time', $id)?><p class="page-lead">Posição #<?=$pos?> · <?=$linha['P']?> pontos · <?=$linha['V']?> V · <?=$linha['VPR']?> VPR · <?=$linha['DPR']?> DPR · <?=$linha['D']?> D · saldo <?=$linha['SG']>=0?'+':''?><?=$linha['SG']?></p></div></section>
<section class="container section"><div class="team-profile-grid"><div class="card"><h2 class="card-title">Campanha e confrontos</h2><div class="table-wrap"><table class="rank-table"><thead><tr><th>Data</th><th>Adversário</th><th>Placar</th><th>Resultado</th></tr></thead><tbody><?php foreach($jogos as $j):$confirmado=(int)$j['confirmado']===1;$vinculo=(int)$j['time_casa']===$id;$res='A jogar';if($confirmado){$res=(int)$j['gf']>(int)$j['ga']?'Vitória':((int)$j['gf']<(int)$j['ga']?'Derrota':'Empate');} ?><tr><td><?=!empty($j['data_hora'])?e(date('d/m H:i',strtotime($j['data_hora']))):'A definir'?></td><td><?=e($j['adversario'])?> <?=botao_favorito($pdo, 'time', (int)$j['time_casa']===$id?(int)$j['time_visitante']:(int)$j['time_casa'])?> <?=botao_favorito($pdo, 'confronto', (int)$j['id'])?></td><td><?=$confirmado?(int)$j['gols_casa'].' × '.(int)$j['gols_visitante']:'— × —'?></td><td><?=$confirmado?e($res):'A jogar'?></td></tr><?php endforeach;?><?php if(!$jogos):?><tr><td colspan="4">Nenhum confronto cadastrado.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card"><h2 class="card-title">Elenco</h2><div class="table-wrap"><table class="rank-table"><thead><tr><th>Camisa</th><th>Jogador</th><th>Jogos</th><th>Gols</th><th>Assist.</th><th>Pontos</th></tr></thead><tbody><?php foreach($elenco as $j):?><tr><td>#<?=(int)$j['numero']?></td><td><?=e($j['nome'])?> <?=botao_favorito($pdo, 'jogador', (int)$j['id'])?></td><td><?=(int)$j['jogos_confirmados']+(int)$j['jogos_ajuste']?></td><td><?=(int)$j['gols']?></td><td><?=(int)$j['assistencias']?></td><td><?=(int)$j['gols']+(int)$j['assistencias']+(int)$j['pontos_ajuste']?></td></tr><?php endforeach;?><?php if(!$elenco):?><tr><td colspan="6">Elenco ainda não cadastrado.</td></tr><?php endif;?></tbody></table></div></div></div></section>
<?php require __DIR__.'/includes/footer.php';?>